	var body strings.Builder
	body.WriteString(`{"schema_version":"1.0","provider":"entire-graph","provider_version":"0.1.0","repo_key":"gh/example/repo","commit":"c1","tree":"t1","capabilities":["go"],"warnings":[],"partial_failures":[]}` + "\n")
